import { AMIGA_DEBRIS } from '../constants/debris.ts';
import type { AmigaEntity, AmigaState } from '../types/index.ts';

/** Original $bedc pool: 210 slots, directions47..0 then15..0 repeatedly.
 * Offset tables are generated by unchanged $83c2 with a fixed cosmetic seed. */
export function spawnAmigaDebris(state: AmigaState, target: AmigaEntity): void {
    const mine = target.kind === 'mine';
    const compact =
        mine ||
        (target.kind === 'turret' && target.type === 0) ||
        (target.kind === 'laser' && target.type === 0);
    const vertical = target.kind === 'laser' && target.type === 1;
    const offsets = compact
        ? AMIGA_DEBRIS.offsets.compact
        : vertical
          ? AMIGA_DEBRIS.offsets.vertical
          : AMIGA_DEBRIS.offsets.wide;
    const style = mine
        ? 1
        : target.kind === 'pod' || (target.kind === 'laser' && target.type === 0)
          ? 2
          : target.kind === 'turret'
            ? target.type === 0
                ? 40
                : 50
            : vertical
              ? 160
              : target.type < 2
                ? 3
                : 0;
    const free =
        210 - state.entities.filter((entity) => entity.alive && entity.kind === 'debris').length;
    for (let index = 0; index < Math.min(free, mine ? 81 : offsets.length); index++) {
        const phase = index < 48 ? 47 - index : 15 - ((index - 48) % 16);
        const [dx, dy] = AMIGA_DEBRIS.velocities[phase]!;
        const [x, y] = offsets[index];
        state.entities.push({
            id: state.nextEntityId++,
            kind: 'debris',
            type: style,
            x: target.x + x,
            y: target.y + y,
            width: 32,
            height: 9,
            frame: 0,
            phase,
            dx,
            dy,
            alive: true,
        });
    }
}
